   1: // POST /groups/:id/import: records a list of expenses and payments in one go, all of them or none. Same handler
   2: // contract as lib/groups.mjs: it returns a new store instead of changing the one it gets.
   3: import { NOT_FOUND, findGroup } from './groups.mjs'
   4: import { balances, expenseView, paymentView } from './ledger.mjs'
   5: import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
   6: 
   7: const BODY_FIELDS = ['entries', 'dry_run', 'skip_recorded']
   8: const MAX_ENTRIES = 50
   9: const ENTRY_FIELDS = {
  10:   expense: ['type', 'description', 'payer', 'amount', 'split'],
  11:   payment: ['type', 'from', 'to', 'amount'],
  12: }
  13: 
  14: // Thrown by an entry check; `rule` is what the 422 reply names.
  15: class RuleError extends Error {
  16:   constructor(rule) {
  17:     super(rule)
  18:     this.rule = rule
  19:   }
  20: }
  21: 
  22: // Runs parse(); a ValidationError from it becomes the given rule.
  23: function check(rule, parse) {
  24:   try {
  25:     return parse()
  26:   } catch (err) {
  27:     if (err instanceof ValidationError) throw new RuleError(rule)
  28:     throw err
  29:   }
  30: }
  31: 
  32: const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v)
  33: 
  34: // Expenses with the same key are the same expense for `duplicate` and `already-recorded`.
  35: const expenseKey = ({ payer, amount, description }) =>
  36:   JSON.stringify([payer, amount, description.trim().toLowerCase()])
  37: 
  38: // The clean fields of one entry, tagged with its type. Throws RuleError on the first rule from not-an-object to
  39: // bad-split (or bad-to / bad-amount for a payment) that the entry breaks.
  40: function parseEntry(entry, members) {
  41:   if (!isObject(entry)) throw new RuleError('not-an-object')
  42:   if (entry.type !== 'expense' && entry.type !== 'payment') throw new RuleError('bad-type')
  43:   const fields = ENTRY_FIELDS[entry.type]
  44:   if (Object.keys(entry).some(key => !fields.includes(key))) throw new RuleError('unknown-field')
  45:   if (entry.type === 'expense') {
  46:     return {
  47:       type: 'expense',
  48:       description: check('bad-description', () => parseDescription(entry.description)),
  49:       payer: check('bad-payer', () => parseMember(entry.payer, members, 'bad payer')),
  50:       amount: check('bad-amount', () => parseAmount(entry.amount)),
  51:       split: check('bad-split', () => parseSplit(Object.hasOwn(entry, 'split') ? entry.split : undefined, members)),
  52:     }
  53:   }
  54:   const from = check('bad-from', () => parseMember(entry.from, members, 'bad from'))
  55:   const to = check('bad-to', () => parseMember(entry.to, members, 'bad to'))
  56:   if (to === from) throw new RuleError('bad-to')
  57:   return { type: 'payment', from, to, amount: check('bad-amount', () => parseAmount(entry.amount)) }
  58: }
  59: 
  60: function parseFlag(body, name) {
  61:   if (!Object.hasOwn(body, name)) return false
  62:   if (typeof body[name] !== 'boolean') throw new ValidationError(`${name} must be true or false`)
  63:   return body[name]
  64: }
  65: 
  66: function parseBody(body) {
  67:   const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
  68:   if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
  69:   const { entries } = body
  70:   if (!Array.isArray(entries) || entries.length < 1 || entries.length > MAX_ENTRIES) {
  71:     throw new ValidationError(`entries must be an array of 1 to ${MAX_ENTRIES} items`)
  72:   }
  73:   return { entries, dryRun: parseFlag(body, 'dry_run'), skipRecorded: parseFlag(body, 'skip_recorded') }
  74: }
  75: 
  76: // Sorts the entries into what to import, what to skip and what is wrong, in entry order.
  77: function sortEntries(entries, group, state, skipRecorded) {
  78:   const recorded = new Set(state.expenses.filter(e => e.group === group.id).map(expenseKey))
  79:   const seen = new Set()
  80:   const accepted = []
  81:   const skipped = []
  82:   const problems = []
  83:   entries.forEach((entry, index) => {
  84:     let parsed
  85:     try {
  86:       parsed = parseEntry(entry, group.members)
  87:     } catch (err) {
  88:       if (!(err instanceof RuleError)) throw err
  89:       problems.push({ index, rule: err.rule })
  90:       return
  91:     }
  92:     // Payments are never duplicate or already recorded. Every valid expense counts for later duplicates, even a
  93:     // duplicate or skipped one.
  94:     const key = parsed.type === 'expense' ? expenseKey(parsed) : null
  95:     if (key !== null && seen.has(key)) problems.push({ index, rule: 'duplicate' })
  96:     else if (key !== null && recorded.has(key) && !skipRecorded) problems.push({ index, rule: 'already-recorded' })
  97:     else if (key !== null && recorded.has(key)) skipped.push(index)
  98:     else accepted.push(parsed)
  99:     if (key !== null) seen.add(key)
 100:   })
 101:   return { accepted, skipped, problems }
 102: }
 103: 
 104: export function importEntries({ state, params, body }) {
 105:   const group = findGroup(state, params[0])
 106:   if (!group) return NOT_FOUND
 107:   const { entries, dryRun, skipRecorded } = parseBody(body)
 108:   const { accepted, skipped, problems } = sortEntries(entries, group, state, skipRecorded)
 109:   if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }
 110: 
 111:   const expenses = []
 112:   const payments = []
 113:   for (const { type, ...fields } of accepted) {
 114:     if (type === 'expense') expenses.push({ id: state.nextExpenseId + expenses.length, group: group.id, ...fields })
 115:     else payments.push({ id: state.nextPaymentId + payments.length, group: group.id, ...fields })
 116:   }
 117:   const next = {
 118:     ...state,
 119:     expenses: [...state.expenses, ...expenses],
 120:     payments: [...state.payments, ...payments],
 121:     nextExpenseId: state.nextExpenseId + expenses.length,
 122:     nextPaymentId: state.nextPaymentId + payments.length,
 123:   }
 124:   const reply = {
 125:     status: dryRun ? 200 : 201,
 126:     body: {
 127:       expenses: expenses.map(expenseView),
 128:       payments: payments.map(paymentView),
 129:       skipped,
 130:       balances: balances(next, group),
 131:     },
 132:   }
 133:   // A dry run, or an import whose entries were all skipped, writes nothing.
 134:   return dryRun || accepted.length === 0 ? reply : { ...reply, state: next }
 135: }
A/lib/validate.mjs
   1: // Input checks for request bodies and query strings. Each parser returns the clean value or throws a
   2: // ValidationError, which the server turns into a 400 reply.
   3: 
   4: export class ValidationError extends Error {
   5:   constructor(message) {
   6:     super(message)
   7:     this.name = 'ValidationError'
   8:   }
   9: }
  10: 
  11: const GROUP_ID = /^[a-z][a-z0-9-]{0,29}$/
  12: const MEMBER_NAME = /^[A-Za-z][A-Za-z0-9_-]{0,29}$/
  13: const MIN_MEMBERS = 2
  14: const MAX_MEMBERS = 20
  15: const MAX_GROUP_NAME_LENGTH = 100
  16: const MAX_DESCRIPTION_LENGTH = 200
  17: const CENTS_PER_UNIT = 100
  18: const MAX_AMOUNT_CENTS = 1_000_000 * CENTS_PER_UNIT
  19: // Digits with at most two decimals, as String() writes a number: "12", "12.5", "4.35".
  20: const TWO_DECIMALS = /^[0-9]+(\.[0-9]{1,2})?$/
  21: 
  22: const AMOUNT_MESSAGE = 'amount must be a number from 0.01 to 1000000 with at most 2 decimals'
  23: const SPLIT_MESSAGE = 'split must be a non-empty list of different members of the group'
  24: 
  25: const isText = (v, max) => typeof v === 'string' && v.trim() !== '' && v.length <= max
  26: 
  27: export function parseGroupId(v) {
  28:   if (typeof v !== 'string' || !GROUP_ID.test(v)) {
  29:     throw new ValidationError('id must be 1 to 30 characters of a-z, 0-9 or -, starting with a letter')
  30:   }
  31:   return v
  32: }
  33: 
  34: export function parseGroupName(v) {
  35:   if (!isText(v, MAX_GROUP_NAME_LENGTH)) {
  36:     throw new ValidationError(`name must be a non-empty string of at most ${MAX_GROUP_NAME_LENGTH} characters`)
  37:   }
  38:   return v
  39: }
  40: 
  41: // A list of 2 to 20 member names, each used once. Names are case-sensitive: "Ann" and "ann" are two people.
  42: export function parseMembers(v) {
  43:   if (!Array.isArray(v) || v.length < MIN_MEMBERS || v.length > MAX_MEMBERS) {
  44:     throw new ValidationError(`members must be an array of ${MIN_MEMBERS} to ${MAX_MEMBERS} names`)
  45:   }
  46:   if (!v.every(name => typeof name === 'string' && MEMBER_NAME.test(name))) {
  47:     throw new ValidationError('member names must be 1 to 30 characters of A-Z, a-z, 0-9, _ or -, starting with a letter')
  48:   }
  49:   if (new Set(v).size !== v.length) throw new ValidationError('members must not repeat a name')
  50:   return [...v]
  51: }
  52: 
  53: export function parseDescription(v) {
  54:   if (!isText(v, MAX_DESCRIPTION_LENGTH)) {
  55:     throw new ValidationError(`description must be a non-empty string of at most ${MAX_DESCRIPTION_LENGTH} characters`)
  56:   }
  57:   return v
  58: }
  59: 
  60: // Amounts arrive as numbers such as 12.5 or 4.35 and are kept as whole cents, so sums never drift.
  61: export function parseAmount(v) {
  62:   if (typeof v !== 'number' || !TWO_DECIMALS.test(String(v))) throw new ValidationError(AMOUNT_MESSAGE)
  63:   // Rounded, not truncated: 4.35 * 100 is 434.99999999999994 in floating point.
  64:   const cents = Math.round(v * CENTS_PER_UNIT)
  65:   if (cents < 1 || cents > MAX_AMOUNT_CENTS) throw new ValidationError(AMOUNT_MESSAGE)
  66:   return cents
  67: }
  68: 
  69: // A name that must belong to one of members; message says which field was wrong.
  70: export function parseMember(v, members, message) {
  71:   if (typeof v !== 'string' || !members.includes(v)) throw new ValidationError(message)
  72:   return v
  73: }
  74: 
  75: // Who shares an expense: a non-empty list of members without repeats. Missing means every member, in group order.
  76: export function parseSplit(v, members) {
  77:   if (v === undefined) return [...members]
  78:   if (!Array.isArray(v) || v.length === 0 || new Set(v).size !== v.length) throw new ValidationError(SPLIT_MESSAGE)
  79:   if (!v.every(name => typeof name === 'string' && members.includes(name))) throw new ValidationError(SPLIT_MESSAGE)
  80:   return [...v]
  81: }
A/lib/ledger.mjs
   1: // Money maths on whole cents: how an expense is shared, what each member is owed or owes, and how to settle up.
   2: // Amounts are stored as cents and shown by the API as numbers (435 cents is 4.35).
   3: 
   4: const CENTS_PER_UNIT = 100
   5: 
   6: export const toAmount = cents => cents / CENTS_PER_UNIT
   7: 
   8: // Each person's part of an amount in cents, as [name, cents] pairs in the order of people. When the cents do
   9: // not divide evenly, the first people pay one cent more each, so the parts always add up to the amount.
  10: export function splitEvenly(cents, people) {
  11:   const share = Math.floor(cents / people.length)
  12:   const extra = cents - share * people.length
  13:   return people.map((name, i) => [name, share + (i < extra ? 1 : 0)])
  14: }
  15: 
  16: // An expense as the API shows it: amounts as numbers, plus each person's share keyed by name.
  17: export function expenseView({ id, description, payer, amount, split }) {
  18:   const shares = Object.fromEntries(splitEvenly(amount, split).map(([name, cents]) => [name, toAmount(cents)]))
  19:   return { id, description, payer, amount: toAmount(amount), split, shares }
  20: }
  21: 
  22: export const paymentView = ({ id, from, to, amount }) => ({ id, from, to, amount: toAmount(amount) })
  23: 
  24: // Each member's balance in cents, as a Map in the group's member order. A payer is owed the whole expense
  25: // minus their own share; a payment from A to B moves A up and B down.
  26: function balanceCents(state, group) {
  27:   const cents = new Map(group.members.map(name => [name, 0]))
  28:   const add = (name, delta) => cents.set(name, cents.get(name) + delta)
  29:   for (const expense of state.expenses.filter(e => e.group === group.id)) {
  30:     add(expense.payer, expense.amount)
  31:     for (const [name, share] of splitEvenly(expense.amount, expense.split)) add(name, -share)
  32:   }
  33:   for (const payment of state.payments.filter(p => p.group === group.id)) {
  34:     add(payment.from, payment.amount)
  35:     add(payment.to, -payment.amount)
  36:   }
  37:   return cents
  38: }
  39: 
  40: // What each member of the group is owed (positive) or owes (negative), in the group's member order.
  41: export function balances(state, group) {
  42:   return Object.fromEntries([...balanceCents(state, group)].map(([name, cents]) => [name, toAmount(cents)]))
  43: }
  44: 
  45: // The member furthest on one side: sign 1 is owed the most, sign -1 owes the most. Ties go to the member who
  46: // comes first in the map; null when nobody is on that side.
  47: function furthest(cents, sign) {
  48:   let best = null
  49:   for (const [name, value] of cents) {
  50:     if (value * sign > 0 && (best === null || value * sign > cents.get(best) * sign)) best = name
  51:   }
  52:   return best
  53: }
  54: 
  55: // Payments that would bring every balance to 0, as [{from, to, amount}]: the member who owes the most pays the
  56: // member who is owed the most whichever is smaller of the two, until nobody owes anything.
  57: export function settleUp(state, group) {
  58:   const left = balanceCents(state, group)
  59:   const payments = []
  60:   let from = furthest(left, -1)
  61:   let to = furthest(left, 1)
  62:   while (from && to) {
  63:     const cents = Math.min(-left.get(from), left.get(to))
  64:     payments.push({ from, to, amount: toAmount(cents) })
  65:     left.set(from, left.get(from) + cents)
  66:     left.set(to, left.get(to) - cents)
  67:     from = furthest(left, -1)
  68:     to = furthest(left, 1)
  69:   }
  70:   return payments
  71: }
A/lib/routes.mjs
   1: // Route table. `takesBody` marks the routes whose JSON body the server reads and passes on as `body`.
   2: import { addExpense, addPayment, deleteExpense, editExpense, listExpenses, listPayments } from './expenses.mjs'
   3: import { createGroup, getBalances, getGroup, getSettleUp } from './groups.mjs'
   4: import { importEntries } from './import.mjs'
   5: 
   6: // Checked in order; the first match wins.
   7: const ROUTES = [
   8:   { method: 'POST', path: /^\/groups$/, handler: createGroup, takesBody: true },
   9:   { method: 'GET', path: /^\/groups\/([^/]+)$/, handler: getGroup },
  10:   { method: 'GET', path: /^\/groups\/([^/]+)\/balances$/, handler: getBalances },
  11:   { method: 'GET', path: /^\/groups\/([^/]+)\/settle-up$/, handler: getSettleUp },
  12:   { method: 'POST', path: /^\/groups\/([^/]+)\/expenses$/, handler: addExpense, takesBody: true },
  13:   { method: 'GET', path: /^\/groups\/([^/]+)\/expenses$/, handler: listExpenses },
  14:   { method: 'PATCH', path: /^\/groups\/([^/]+)\/expenses\/([^/]+)$/, handler: editExpense, takesBody: true },
  15:   { method: 'DELETE', path: /^\/groups\/([^/]+)\/expenses\/([^/]+)$/, handler: deleteExpense },
  16:   { method: 'POST', path: /^\/groups\/([^/]+)\/payments$/, handler: addPayment, takesBody: true },
  17:   { method: 'GET', path: /^\/groups\/([^/]+)\/payments$/, handler: listPayments },
  18:   { method: 'POST', path: /^\/groups\/([^/]+)\/import$/, handler: importEntries, takesBody: true },
  19: ]
  20: 
  21: // Returns { handler, params, takesBody } for the first route matching method and pathname, or null.
  22: export function findRoute(method, pathname) {
  23:   for (const { method: m, path, handler, takesBody = false } of ROUTES) {
  24:     const match = m === method && path.exec(pathname)
  25:     if (match) return { handler, params: match.slice(1), takesBody }
  26:   }
  27:   return null
  28: }
A/lib/expenses.mjs
   1: // Expense and payment handlers, same contract as lib/groups.mjs: they return a new store instead of changing
   2: // the one they get.
   3: import { NOT_FOUND, findGroup } from './groups.mjs'
   4: import { expenseView, paymentView } from './ledger.mjs'
   5: import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
   6: 
   7: const byId = (a, b) => a.id - b.id
   8: 
   9: // The fields of a new expense in group, from a request body. Throws ValidationError on the first bad field.
  10: export function parseExpense(group, body) {
  11:   return {
  12:     description: parseDescription(body.description),
  13:     payer: parseMember(body.payer, group.members, 'payer must be a member of the group'),
  14:     amount: parseAmount(body.amount),
  15:     split: parseSplit(body.split, group.members),
  16:   }
  17: }
  18: 
  19: export function addExpense({ state, params, body }) {
  20:   const group = findGroup(state, params[0])
  21:   if (!group) return NOT_FOUND
  22:   const expense = { id: state.nextExpenseId, group: group.id, ...parseExpense(group, body) }
  23:   const next = { ...state, expenses: [...state.expenses, expense], nextExpenseId: state.nextExpenseId + 1 }
  24:   return { status: 201, body: expenseView(expense), state: next }
  25: }
  26: 
  27: export function listExpenses({ state, params }) {
  28:   const group = findGroup(state, params[0])
  29:   if (!group) return NOT_FOUND
  30:   const expenses = state.expenses.filter(e => e.group === group.id).sort(byId).map(expenseView)
  31:   return { status: 200, body: { expenses } }
  32: }
  33: 
  34: const findExpense = (state, [groupId, expenseId]) =>
  35:   state.expenses.find(e => e.group === groupId && String(e.id) === expenseId)
  36: 
  37: // Changes the fields the body gives, each checked as on POST; fields left out keep their value.
  38: export function editExpense({ state, params, body }) {
  39:   const group = findGroup(state, params[0])
  40:   const old = group && findExpense(state, params)
  41:   if (!old) return NOT_FOUND
  42:   const changes = {}
  43:   if ('description' in body) changes.description = parseDescription(body.description)
  44:   if ('payer' in body) changes.payer = parseMember(body.payer, group.members, 'payer must be a member of the group')
  45:   if ('amount' in body) changes.amount = parseAmount(body.amount)
  46:   if ('split' in body) changes.split = parseSplit(body.split, group.members)
  47:   const edited = { ...old, ...changes }
  48:   const next = { ...state, expenses: state.expenses.map(e => (e === old ? edited : e)) }
  49:   return { status: 200, body: expenseView(edited), state: next }
  50: }
  51: 
  52: export function deleteExpense({ state, params }) {
  53:   const expense = findExpense(state, params)
  54:   if (!expense) return NOT_FOUND
  55:   return { status: 204, state: { ...state, expenses: state.expenses.filter(e => e !== expense) } }
  56: }
  57: 
  58: export function addPayment({ state, params, body }) {
  59:   const group = findGroup(state, params[0])
  60:   if (!group) return NOT_FOUND
  61:   const message = 'from and to must be two different members of the group'
  62:   const from = parseMember(body.from, group.members, message)
  63:   const to = parseMember(body.to, group.members, message)
  64:   if (from === to) throw new ValidationError(message)
  65:   const payment = { id: state.nextPaymentId, group: group.id, from, to, amount: parseAmount(body.amount) }
  66:   const next = { ...state, payments: [...state.payments, payment], nextPaymentId: state.nextPaymentId + 1 }
  67:   return { status: 201, body: paymentView(payment), state: next }
  68: }
  69: 
  70: export function listPayments({ state, params }) {
  71:   const group = findGroup(state, params[0])
  72:   if (!group) return NOT_FOUND
  73:   const payments = state.payments.filter(p => p.group === group.id).sort(byId).map(paymentView)
  74:   return { status: 200, body: { payments } }
  75: }
A/lib/http.mjs
   1: // HTTP helpers: reading a JSON body, sending JSON replies and turning errors into replies.
   2: import { ValidationError } from './validate.mjs'
   3: 
   4: export const MAX_BODY_BYTES = 10 * 1024
   5: 
   6: export class HttpError extends Error {
   7:   constructor(status, message) {
   8:     super(message)
   9:     this.status = status
  10:   }
  11: }
  12: 
  13: // Reads the whole body as UTF-8. Past MAX_BODY_BYTES it stops keeping chunks but still drains the upload,
  14: // so the 413 reply reaches the client instead of a reset connection.
  15: export function readBody(req) {
  16:   return new Promise((resolve, reject) => {
  17:     const chunks = []
  18:     let size = 0
  19:     req.on('data', chunk => {
  20:       size += chunk.length
  21:       if (size <= MAX_BODY_BYTES) chunks.push(chunk)
  22:     })
  23:     req.on('end', () => {
  24:       if (size > MAX_BODY_BYTES) reject(new HttpError(413, 'body too large'))
  25:       else resolve(Buffer.concat(chunks).toString('utf8'))
  26:     })
  27:     req.on('error', reject)
  28:   })
  29: }
  30: 
  31: export function parseJsonObject(text) {
  32:   let value
  33:   try {
  34:     value = JSON.parse(text)
  35:   } catch {
  36:     throw new HttpError(400, 'invalid JSON')
  37:   }
  38:   if (value === null || typeof value !== 'object' || Array.isArray(value)) {
  39:     throw new HttpError(400, 'body must be a JSON object')
  40:   }
  41:   return value
  42: }
  43: 
  44: // Sends { status, body }: body as JSON, or no body at all when it is undefined (204).
  45: export function send(res, { status, body }) {
  46:   if (body === undefined) {
  47:     res.writeHead(status).end()
  48:     return
  49:   }
  50:   const text = JSON.stringify(body)
  51:   res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text) })
  52:   res.end(text)
  53: }
  54: 
  55: export function errorReply(err) {
  56:   if (err instanceof HttpError) return { status: err.status, body: { error: err.message } }
  57:   if (err instanceof ValidationError) return { status: 400, body: { error: err.message } }
  58:   // An OS error (ENOENT, EACCES, ...) is logged as one line; any other error keeps its stack.
  59:   console.error(err.code ? [err.code, err.syscall, err.path].filter(Boolean).join(' ') : err)
  60:   return { status: 500, body: { error: 'internal error' } }
  61: }
